/* Types */
export type Accent = "red" | "orange" | "green" | "teal" | "blue" | "purple" | "pink" | 
/**  `Settings::accent_color` (M46.7). */
"custom";

/**  Where a permission stands. */
export type AccessState = 
/**  Allowed (battery: unrestricted). */
"granted" | 
/**  Not allowed; asking shows the system's question. */
"denied" | 
/**  Not allowed, and only the system settings can change it now. */
"blocked" | 
/**  Battery: Android's default limits apply (asking shows its question). */
"optimized" | 
/**
 *  Battery: restricted in the background, so playback and downloads stop when Raygun leaves
 *  the screen; only the system settings can lift it.
 */
"restricted";

export type AiModel = {
	id: string,
	name: string,
	kind: string,
	description: string,
	license: string,
	licenseUrl: string,
	sourceUrl: string,
	sizeBytes: number | null,
	installed: boolean,
	/**  Bytes received while a download is running. */
	downloading: number | null,
	/**
	 *  What runs it, for models Raygun runs in more than one way: `anime4k` (the readers' upscale
	 *  and restore layers run these on the graphics card), `ncnn` (no runner in this build yet).
	 */
	engine?: string | null,
};

/**  A model download's progress (M34). */
export type AiModelEvent = AiModelProgress;

export type AiModelProgress = {
	id: string,
	state: AiModelState,
	receivedBytes: number | null,
	totalBytes: number | null,
	error: string | null,
};

/**
 *  Where a model's download is. `ai_model_download` answers with how it ended: `Installed`, or
 *  `Cancelled` (nothing of it was kept, an installed copy stays as it was).
 */
export type AiModelState = "downloading" | "installed" | "failed" | "cancelled";

/**  A configured translator. Its key stays in the secrets store; only a hint is shown. */
export type AiProvider = {
	id: string,
	kind: AiProviderKind,
	name: string,
	baseUrl: string | null,
	model: string | null,
	hasKey: boolean,
	/**  The key's last four characters. */
	keyHint: string | null,
};

/**  A provider to add (no `id`) or change. */
export type AiProviderInput = {
	id: string | null,
	kind: AiProviderKind,
	name: string,
	baseUrl: string | null,
	model: string | null,
	/**  `null` keeps the stored key; an empty string removes it. */
	key: string | null,
};

export type AiProviderKind = "claude" | "openAiCompatible" | "deepl" | 
/**  A LibreTranslate server (self-hosted or public; key optional). */
"libreTranslate" | 
/**  MyMemory's free translations (anonymous; the key slot holds an optional email). */
"myMemory" | 
/**
 *  An OpenAI-compatible transcription server (faster-whisper-server, whisper.cpp): only
 *  transcribes.
 */
"whisperServer" | 
/**
 *  Google's Cloud Translation API (Basic, v2) with the user's API key. Its translations are
 *  shown with Google's attribution.
 */
"google";

/**  An anime episode, for looking up its openings and endings on AniSkip (M45). */
export type AnimeEpisode = {
	/**  The series' name, searched on AniList when there is no MyAnimeList id. */
	title: string,
	episode: number,
	malId: number | null,
	/**
	 *  The entry's Kitsu or AniList id, whose MyAnimeList id is looked up before searching by
	 *  name (each season has its own).
	 */
	kitsuId?: number | null,
	anilistId?: number | null,
};

/**  One answer to a question. */
export type Answer = {
	/**
	 *  Who answered: `raygun` (computed on this device), `wikidata`, `wikipedia`, `dictionary`,
	 *  `translation`, `ecb`, or an extension's `<extension>/<provider>`.
	 */
	engine: string,
	/**  Empty for Raygun's own engines, which the app names itself. */
	engineName: string,
	kind: AnswerKind,
	/**  How the words were read ("Input interpretation"). */
	interpretation: AnswerText | null,
	result: AnswerText,
	/**  The result is rounded. */
	approximate: boolean,
	/**  Other forms of the result, other facts. */
	rows: AnswerRow[],
	/**  The result in other units. */
	units: AnswerUnit[],
	/**  A paragraph about it (a Wikipedia article's start). */
	summary: string | null,
	/**  A picture, through Raygun's cover proxy. */
	imageUrl: string | null,
	/**  Where to read more. */
	url: string | null,
	credits: AnswerCredit[],
	/**  When the value stands (a population's count, the exchange rates' day). */
	asOf: AnswerDate | null,
	/**  Plain text Copy puts on the clipboard. */
	copy: string,
	/**  This device's copy of an earlier answer. */
	kept: boolean,
};

/**  Who an answer comes from. */
export type AnswerCredit = {
	name: string,
	url: string | null,
	/**  `CC0`, `CC BY-SA 4.0`… */
	license: string | null,
	licenseUrl: string | null,
};

/**  A date shown in the app's language. */
export type AnswerDate = {
	/**
	 *  `2027-01-01`, `-0500-01-01` before the common era; with a time of day,
	 *  `2027-01-01T15:30` (the clock time where it's said, no offset).
	 */
	iso: string,
	precision: AnswerDatePrecision,
};

/**  How much of a date is known. */
export type AnswerDatePrecision = "century" | "decade" | "year" | "month" | "day" | 
/**  A day and a time of day. */
"minute";

/**  What an answer is. */
export type AnswerKind = "calculation" | "conversion" | "currency" | "percentage" | "numberBase" | "statistics" | "algebra" | "constant" | "date" | "time" | "fact" | "summary" | "definition" | "translation" | "other";

/**  A formula, drawn by the webview from MathML. */
export type AnswerMath = {
	/**  `<math>…</math>`: MathML elements and attributes only. */
	mathml: string,
	/**  The formula as text (its TeX, or a linear form). */
	text: string,
	/**  The formula in words, for screen readers. */
	speech: string,
};

/**  A question asked in Search. */
export type AnswerRequest = {
	query: string,
	/**
	 *  For Search → All's card: answered only when the words read as a question or a
	 *  calculation, by the quick engines. Otherwise it's the Answers pill: every engine, and
	 *  more about each answer.
	 */
	card?: boolean,
	/**  The app's language (BCP 47): the language of facts' names and of summaries. */
	language: string,
	/**  This device's time zone (IANA, `Europe/Paris`), for dates and times. */
	timeZone?: string | null,
	/**  Minutes east of UTC now, for when the zone isn't known. */
	utcOffsetMinutes?: number,
	/**  Asks the online engines again, even when this device kept a recent answer. */
	refresh?: boolean,
};

/**  One line of an answer: another form of the result, another fact. */
export type AnswerRow = {
	/**
	 *  What the app names in its language (`decimal`, `fraction`, `words`, `rate`…); empty when
	 *  `label` is shown as it is.
	 */
	key: string,
	/**  The name in English, or as an engine gave it. */
	label: string,
	value: AnswerText,
};

/**  Something else to ask. */
export type AnswerSuggestion = {
	label: string,
	query: string,
};

/**
 *  Text in an answer: maybe a formula or a date the app shows its own way, maybe something to
 *  ask about next.
 */
export type AnswerText = {
	/**  Always set: what's copied, and shown when the formula or date can't be. */
	text: string,
	math: AnswerMath | null,
	date: AnswerDate | null,
	/**  Asking this tells more about it (a director's name: who they are). */
	query: string | null,
};

