export type ConnectDevice = {
	id: string,
	name: string,
	/**  `host:port`. */
	address: string,
	/**  `phone` or `computer`. */
	kind: string,
	/**  It allowed this device before, so playing there asks nothing. */
	paired: boolean,
	/**  Heard on the network, or reached at its address, this run. */
	found: boolean,
	/**  Linked (M46.47): its sync id; the two keep each other in sync. */
	syncId: string | null,
	/**  When the two last synced (Unix ms). */
	lastSyncAt: number | null,
};

/**  Where this device's player plays changed, or the device it plays on reported (M46.15). */
export type ConnectEvent = ConnectStatus;

/**  Another device asks to play on this one (M46.15); `open` is false once it's answered or gone. */
export type ConnectRequest = {
	id: string,
	name: string,
	open: boolean,
};

/**  Another device asks to play on this one, or the question closed (M46.15). */
export type ConnectRequestEvent = ConnectRequest;

/**  Playing on another device (M46.15): which one, and its player as it last reported. */
export type ConnectSession = {
	deviceId: string,
	deviceName: string,
	/**  `phone` or `computer`. */
	deviceKind: string,
	state: PlaybackState | null,
	queue: QueueSnapshot | null,
};

/**  Where this device's player plays (M46.15). */
export type ConnectStatus = {
	/**  This device's name, as others see it. */
	thisDevice: string,
	/**  Set while playing on another device. */
	session: ConnectSession | null,
	/**  The device being asked, until it answers. */
	asking: string | null,
	/**  What went wrong last: a refusal, a device that went away. */
	error: string | null,
};

/**  A rating the user gives a source, an extension or a repository over its own. */
export type ContentOverride = 
/**  The source's own rating. */
"default" | "adult" | "notAdult";

/**  18+ marks set by the user: per extension id, per repository id, per Stremio addon id. */
export type ContentOverrides = {
	extensions?: { [key in string]: ContentOverride },
	repositories?: { [key in string]: ContentOverride },
	addons?: { [key in string]: ContentOverride },
};

/**  Something started and not finished. */
export type ContinueWatching = {
	key: string,
	title: string,
	subtitle: string | null,
	poster: string | null,
	positionMs: number | null,
	durationMs: number | null,
	/**  Unix ms. */
	updatedAt: number | null,
	watched: boolean,
	/**
	 *  The title it belongs to, for its page: a video source's id (or `stremio`, then
	 *  `remote_id` is `<type>:<id>`). None for a link played on its own.
	 */
	sourceId?: string | null,
	remoteId?: string | null,
	/**
	 *  The title's player group (`title:<id>` for a video source's stored title, or
	 *  `stremio:<type>:<id>`), which episode downloads take. None for a link played on its own.
	 */
	group?: string | null,
	/**
	 *  The movie's or episode's id at its source (Stremio: the video id), for picking its
	 *  source or downloading it.
	 */
	episodeId?: string | null,
	/**  The stored episode of a video source's title, which its servers are listed for. */
	unitId?: string | null,
	/**  An episode of a series, which may have a next one to move on to. */
	series?: boolean,
	/**  A link played on its own (Open link, another app): its page is `/watch/link?key=`. */
	link?: boolean,
};

/**  A cover a source has for a song, an album or an artist (M46.36), offered in Edit details. */
export type CoverOption = {
	/**  The image's address at the source (stored as is when picked). */
	url: string,
	/**  The source's name. */
	source: string,
	/**  What it's the cover of, when that isn't the thing edited (a song's album). */
	of: string | null,
};

export type CoverStyle = "compact" | "comfortable";

/**  About → Crash logs. */
export type CrashLogs = {
	records: CrashRecord[],
	/**  Every extension held back. */
	heldBack: SourceRef[],
	/**  The logs folder, as a path. */
	folder: string,
	safeStart: SafeStartInfo,
};

/**  One record, as the list shows it. */
export type CrashRecord = {
	/**  Its file name. */
	id: string,
	/**  `panic`, `java`, `renderer`, `native`, `anr`, `memory`, `exit` or `start`. */
	kind: string,
	/**  When, in milliseconds since 1970. */
	at: number | null,
	summary: string,
};

/**  People with one role on a song (M46.14): "Written by", "Produced by", "Guitar"... */
export type CreditGroup = {
	role: string,
	names: string[],
};

/**
 *  Colours the user picked instead of the theme's (M46.8): each `#rrggbb`, or empty for the
 *  theme's own. The accent has its own setting.
 */
export type CustomColors = {
	/**  The page behind everything. */
	background?: string,
	/**  Cards, bars, panels and sheets. */
	surface?: string,
	/**  Text and icons. */
	foreground?: string,
	/**  Secondary text and icons. */
	muted?: string,
};

/**  One kind of data Settings → Data backs up, restores and clears. */
export type DataCategory = 
/**  Library → Comics, with chapters, what was read and categories. */
"comics" | 
/**  Library → Books. */
"books" | 
/**  Library → Videos. */
"videos" | 
/**  Followed podcasts and where each episode was left. */
"podcasts" | "audiobooks" | 
/**  Sites added to the built-in browser. */
"websites" | 
/**  Playlists and favorite songs. */
"playlists" | 
/**  Quick access: its pins and when its pages were last played from. */
"pins" | 
/**  Songs played, videos watched and what was played from. */
"history" | 
/**  Every setting but quick access's. */
"settings" | 
/**  Extensions, repositories, Stremio addons and connected servers. */
"sources" | 
/**  What was downloaded: backups keep the list, never the files. */
"downloads" | 
/**
 *  Local Files' folders: where Raygun looks for songs, comics, books and videos on this
 *  device. Backups keep the list, and a restore adds back the folders this device has.
 */
"localFiles" | 
/**  Recent searches. */
"searches" | 
/**  AI models and translators. */
"aiModels" | 
/**
 *  Covers, reader pages, lyrics, videos' AI subtitles and songs opened from other apps, kept
 *  to show or play them quickly; never backed up.
 */
"caches";

export type DataCount = {
	item: DataItem,
	count: number,
	/**  What its files take on this device, where it's files. */
	bytes: number | null,
};

/**  What a count in Settings → Data or a backup's index counts. */
export type DataItem = "titles" | "chapters" | "read" | "episodes" | "watched" | "categories" | "shows" | "books" | "sites" | "playlists" | "playlistSongs" | "favorites" | "pins" | 
/**  Pages quick access sorts by when they were last played from. */
"played" | "settings" | "repositories" | "extensions" | "addons" | "servers" | 
/**  Passwords, sign-ins and API keys. */
"secrets" | "plays" | 
/**  Places music was played from (an album, a playlist…). */
"contexts" | 
/**  Downloaded songs. */
"songs" | 
/**  Downloaded videos. */
"videos" | 
/**  Downloads waiting or failed: entries without a file. */
"waiting" | 
/**  Files saved from websites. */
"files" | 
/**  Local Files' folders. */
"folders" | "searches" | "models" | "translators" | "covers" | "pages" | "lyrics" | 
/**  Videos with AI subtitles or translated subtitles kept. */
"subtitles" | 
/**  Songs other apps opened with Raygun, copied to play them. */
"opened";

/**
 *  Data Saver: the same things for less data. Each part can be turned off on its own; with Data
 *  Saver on, the defaults save the most. It changes how other settings apply
 *  ([`Settings::with_data_saver`]) rather than the settings themselves.
 */
export type DataSaverPrefs = {
	enabled?: boolean,
	/**  Only while the device is on mobile data. */
	mobileDataOnly?: boolean,
	/**  Videos play at most at `video_resolution`. */
	limitVideo?: boolean,
	videoResolution?: VideoResolution,
	/**  Songs stream at `music_quality` at most. */
	limitMusic?: boolean,
	musicQuality?: AudioQuality,
	/**  Fewer sources asked at once, and fewer listing pages read for a search. */
	fewerSources?: boolean,
	/**  The songs before and after the one playing aren't found ahead. */
	noPrefetch?: boolean,
	/**  Nothing is looked up in the background: covers, song tags, song lengths. */
	noBackgroundLookups?: boolean,
	/**  Smaller covers from sources that offer several sizes. */
	smallerCovers?: boolean,
	/**  Trailers on title pages don't play by themselves. */
	noTrailers?: boolean,
	/**  Pictures load only once they're on screen. */
	imagesWhenVisible?: boolean,
};

/**  Where clearing a category reaches. */
export type DataScope = 
/**  Linked devices remove it too: device sync carries the clear like any change. */
"synced" | 
/**  This device only. */
"device";

/**  One category in Settings → Data: what's in it on this device. */
export type DataUsage = {
	category: DataCategory,
	counts: DataCount[],
	/**  Bytes its files take (downloads, models, caches); 0 for rows in the database. */
	bytes: number | null,
	scope: DataScope,
};

/**  Which decoders play video. */
export type DecoderMode = 
/**  Hardware, falling back to software when it fails. */
"auto" | 
/**  Software first: slower, but plays what the hardware can't. */
"software";

/**
 *  The user's own details (M46.30); `None` keeps what the source said. For an album `title` is
 *  its title, for an artist their name; `artist` and `album` are songs' only.
 */
export type DetailEdit = {
	title: string | null,
	artist: string | null,
	album: string | null,
	artworkUrl: string | null,
};

/**
 *  What the user edits the details of (M46.30): a song, an album or an artist; a playlist's
 *  cover (M46.45).
 */
export type DetailTarget = { kind: "song"; query: TrackQuery } | { kind: "album"; artist: string | null; album: string } | { kind: "artist"; name: string } | 
/**  Only its cover is the user's (its name is renamed with the playlist). */
{ kind: "playlist"; id: string };

/**  What an address added in Sources is (M46.52). */
export type DetectedKind = 
/**  A Stremio addon (its `manifest.json`). */
"addon" | 
/**  A repository of extensions, in one app's format. */
"repository" | 
/**  One extension on its own: a Raygun package, a Miru or Shosetsu script. */
"extension" | 
/**  A server people sign in to: Jellyfin, Emby, Subsonic, Audiobookshelf, an OPDS catalogue. */
"server";

/**  An address read before it's added (Sources → Add), and what adding it brought. */
export type DetectedSource = {
	kind: DetectedKind,
	/**  A repository's or an extension's format. */
	format: SourceFormat | null,
	/**  A server's kind. */
	server: ServerKind | null,
	/**
	 *  What it's added by: the addon's manifest, the repository's index, the extension's file,
	 *  the server's address.
	 */
	url: string,
	name: string,
	description: string | null,
	/**
	 *  Already on this device: the addon, the repository, the extension at this version, the
	 *  server.
	 */
	added: boolean,
	/**  The addon, as the list shows it. */
	addon: StremioAddon | null,
	/**  What the repository lists, or the one extension. */
	entries: CatalogEntry[],
	/**  Why its extensions can't run here (a Kodi or Mihon repository), when they can't. */
	note: string | null,
};

/**  The device's state as the UI sees it. */
export type DeviceState = {
	/**  Raygun is on screen (an activity started on Android; the webview visible). */
	foreground: boolean,
	/**  Battery saver is on. */
	powerSave: boolean,
	/**  The system's animation settings. */
	motion: SystemMotion,
};

/**  The device's state changed. */
export type DeviceStateEvent = DeviceState;

/**  A source that answered, credited under the answer with a link to its full entry. */
export type DictionaryCredit = {
	source: string,
	name: string,
	url: string | null,
	license: DictionaryLicense | null,
};

/**  One sense of a word. */
export type DictionaryDefinition = {
	text: string,
	/**  Sentences using the word in this sense. */
	examples: string[],
};

/**  The word is a form of another (`went`: simple past of `go`). */
export type DictionaryFormOf = {
	/**  The form looked up. */
	form: string,
	/**  The word it's a form of, whose entry is shown. */
	lemma: string,
	/**  What the source says the form is (`simple past of go`). */
	note: string,
	/**
	 *  Every sense the source gives is a form of the lemma (`ran`), so the lemma's entry is
	 *  what's shown; otherwise (`building`) the word's own senses are, with the lemma offered.
	 */
	only?: boolean,
};

/**  The licence a source's text comes under. */
export type DictionaryLicense = {
	/**  `CC BY-SA 4.0`. */
	name: string,
	url: string | null,
};

/**  What the dictionaries say about a selection, merged in the order of the user's sources. */
export type DictionaryLookup = {
	/**  The selection, tidied (surrounding punctuation and spaces left out). */
	query: string,
	/**  The headword shown; empty when no source knew the word. */
	word: string,
	/**  The language looked up in, a BCP 47 tag. */
	language: string,
	languageName: string | null,
	formOf: DictionaryFormOf | null,
	pronunciations: DictionaryPronunciation[],
	meanings: DictionaryMeaning[],
	etymology: string | null,
	credits: DictionaryCredit[],
	/**  Searches the web's dictionaries for the selection (Wiktionary's search). */
	onlineUrl: string,
	/**  The answer is what this device kept from an earlier lookup. */
	kept: boolean,
	/**  Offline Mode is on and nothing was kept for the word. */
	offline: boolean,
	/**  Sources that had trouble, one sentence each. */
	issues: string[],
};

/**  The word as one part of speech. */
export type DictionaryMeaning = {
	/**  As the source names it, in lower case (`noun`, `verb`, `proper noun`). */
	partOfSpeech: string,
	definitions: DictionaryDefinition[],
	synonyms: string[],
	antonyms: string[],
	translations: DictionaryTranslation[],
};

/**  The book reader's dictionary (Settings → Reader). */
export type DictionaryPrefs = {
	/**
	 *  Selecting words in the book reader looks them up; off, the text isn't selectable and a
	 *  long press reads aloud from the paragraph, as before.
	 */
	enabled?: boolean,
	/**
	 *  Sources in the order they're asked and shown (`wiktionary`, `freeDictionary`, an
	 *  extension's `<extension>/<provider>`); sources not listed come after them.
	 */
	order?: string[],
	/**  Sources turned off. */
	off?: string[],
	/**  The words' language as a BCP 47 tag; empty takes the book's language, then the app's. */
	language?: string,
};

/**  How a word sounds: a transcription, a recording, or both. */
export type DictionaryPronunciation = {
	/**  IPA, with its slashes or brackets (`/ˈhæpi/`). */
	ipa: string | null,
	/**  Whose pronunciation: an accent or a region (`UK`, `General American`). */
	label: string | null,
	/**  A recording. In a lookup's answer, a link through Raygun's own proxy. */
	audioUrl: string | null,
};

/**  A word or phrase selected in the reader, to look up. */
export type DictionaryRequest = {
	/**  The selection as it was made. */
	text: string,
	/**  The book it's in: its language is the words' language. */
	titleId: string | null,
	/**
	 *  The app's language as the UI resolved it (a BCP 47 tag): the words' language when the
	 *  book's isn't known, and the language translations are shown in.
	 */
	appLanguage: string,
	/**  Asks the sources again, even when this device kept a recent answer. */
	refresh?: boolean,
};

/**  A dictionary source, for Settings. */
export type DictionarySourceInfo = {
	/**  `wiktionary`, `freeDictionary`, or an extension's `<extension>/<provider>`. */
	id: string,
	name: string,
	/**  The languages it knows words of, as BCP 47 tags; empty for any. */
	languages: string[],
	/**  Raygun's own, or an extension's. */
	builtIn: boolean,
	enabled: boolean,
};

/**  The word in another language: the app's. */
export type DictionaryTranslation = {
	/**  The sense translated (`contented, joyous`), when the source tells senses apart. */
	gloss: string | null,
	/**  The language the terms are in, a BCP 47 tag. */
	language: string,
	terms: string[],
};

/**  Charts and song tags (M46.9). */
export type DiscoveryPrefs = {
	/**  The charts' country, an ISO 3166 code in lowercase ("gb"); empty follows the app language. */
	region?: string,
	/**  Find genres and moods for saved songs in the background. */
	tagSongs?: boolean,
};

export type DownloadState = "queued" | "downloading" | "done" | "failed";

/**  What clearing downloads removes. */
export type DownloadsClear = 
/**  Downloaded files and their entries. Copies saved outside Raygun stay. */
"files" | 
/**  Entries waiting or failed, which have no file yet. */
"records";

/**  Lyrics a person wrote or corrected for a song (M46.12), replacing what sources have. */
export type EditedLyrics = {
	/**  Sorted by time; empty when the lyrics are plain. */
	synced?: LyricLine[],
	plain?: string | null,
};

/**  An instruction for the active playback engine. */
export type EngineCommand = { type: "load"; loadId: number; url: string; 
/**
 *  `url` is an HLS playlist (through the proxy's `/media/` route, which brings its
 *  pieces through the proxy too): the engine plays it with its HLS reader.
 */
hls?: boolean; 
/**  For native engines' media session (notification, lock screen). */
title: string; artist: string | null; artworkUrl: string | null; startMs: number | null; autoplay: boolean; volume: number | null; 
/**  This song's gain in dB: its own volume plus normalization (M46.12). */
gainDb: number | null; 
/**  Where the song ends (its end trim), ms; the engine reports `Ended` there. */
endMs: number | null; 
/**  Fade from what plays now into this song over this long (a crossfade), ms; 0 cuts. */
fadeMs: number | null; 
/**  Measure this song's loudness and report it (it isn't known yet). */
measure: boolean } | 
/**
 *  Plays a YouTube video in the embedded player hosted at `embed_url` (webview only). Only its
 *  volume can change: `gain_db` scales it down, never up.
 */
{ type: "loadYouTube"; loadId: number; embedUrl: string; videoId: string; startMs: number | null; autoplay: boolean; volume: number | null; gainDb: number | null; endMs: number | null; fadeMs: number | null } | { type: "play" } | { type: "pause" } | { type: "seek"; positionMs: number | null } | { type: "setVolume"; volume: number | null } | 
/**  Playback speed (M46.8); engines keep it across loads. */
{ type: "setRate"; rate: number | null } | 
/**  The equalizer and effects for every song (M46.12); engines keep them across loads. */
{ type: "setEffects"; sound: SoundPrefs } | 
/**  The playing song's gain changed (its volume was edited), dB. */
{ type: "setTrackGain"; gainDb: number | null } | 
/**  The playing song's end trim changed, ms. */
{ type: "setEnd"; endMs: number | null } | 
/**  Fades the playing song out over `fade_ms`, then stops (another engine takes over). */
{ type: "fadeOut"; fadeMs: number | null } | { type: "stop" };

/**  An instruction for the playback engine running in the webview. */
export type EngineCommandEvent = EngineCommand;

export type EngineEvent = { type: "progress"; positionMs: number | null; durationMs: number | null } | { type: "playing" } | { type: "paused" } | { type: "buffering" } | { type: "ended" } | { type: "error"; message: string } | 
/**  The song's integrated loudness, measured while it played (M46.12). */
{ type: "loudness"; lufs: number | null };

/**
 *  What the engine observed. `load_id` ties it to a specific `Load`, so reports about a track
 *  that has already been replaced are ignored.
 */
export type EngineReport = {
	loadId: number,
	event: EngineEvent,
};

export type EpisodeDownload = {
	state: EpisodeDownloadState,
	receivedBytes: number | null,
	totalBytes: number | null,
	error: string | null,
};

export type EpisodeDownloadState = 
/**  Waiting for another download to finish (M46.48: two at a time). */
"queued" | "downloading" | "done" | "failed";

/**  Which episodes show (M46.48); several at once must all hold. */
export type EpisodeFilter = "unplayed" | "started" | "downloaded";

/**  How a show's or book's episodes list, kept per show (M46.48). */
export type EpisodeOrder = {
	sort: EpisodeSort,
	/**  Newest, highest, longest or last first. */
	descending: boolean,
	filters: EpisodeFilter[],
};

/**  What a show's or book's episodes are sorted by (M46.48). */
export type EpisodeSort = 
/**  Release date. */
"date" | 
/**  Episode number, or a book's chapter order. */
"number" | "title" | "duration" | 
/**  Started ones, then the rest not played, then the played. */
"unplayed";

/**
 *  What a video format does with the episodes already downloaded: streams copied as they are, or
 *  re-encoded (the picture to H.264, the sound to AAC or MP3) where the format can't hold them as a
 *  file every player plays.
 */
export type ExportConversion = {
	format: ExportFormat,
	/**  The picture is re-encoded, for at least one episode. */
	video: boolean,
	/**  The sound is re-encoded, for at least one episode. */
	audio: boolean,
	/**  What's re-encoded from, as people know the codecs ("VP9", "Opus"). */
	from: string[],
	/**  About how long writing the files takes, in seconds (when the lengths are known). */
	seconds: number | null,
	/**  Re-encoding needs FFmpeg, which isn't on this computer yet. */
	needsFfmpeg: boolean,
};

/**  Where an export's files go. */
export type ExportDestination = 
/**  `Download/Raygun/`. */
"downloads" | 
/**  The request's `folder`, else the folder picked in Settings → Downloads. */
"folder" | 
/**  The share sheet (one file). */
"share";

/**  An export job changed (M46.1); carries the job, or nothing when one was removed from the list. */
export type ExportEvent = ExportJob | null;

/**  A folder exports can be written to: its tree URI on Android or its path on desktop. */
export type ExportFolder = {
	uri: string,
	name: string,
};

/**  What an export writes. */
export type ExportFormat = 
/**  Manga: one CBZ (with ComicInfo.xml) per chapter. */
"cbz" | 
/**  Manga: one PDF for everything chosen, a bookmark per chapter. */
"pdf" | 
/**  Manga: one PDF per chapter. */
"pdfPerChapter" | 
/**  Manga: a folder of page images per chapter. */
"images" | 
/**  Novels: one EPUB book. */
"epub" | 
/**  Novels: one text file. */
"text" | 
/**
 *  Videos: each downloaded episode as one file in the format it downloaded in (an HLS
 *  stream's segments joined: MPEG-TS or fragmented MP4).
 */
"video" | 
/**  Videos: MP4 with H.264 and AAC, copied when they're that already, else re-encoded. */
"mp4" | 
/**  Videos: Matroska, streams copied (re-encoded only where a phone can't carry them). */
"mkv" | 
/**  Videos: the sound alone, AAC in an M4A file (re-encoded unless it is AAC). */
"m4a" | 
/**  Videos: the sound alone as MP3 (encoded unless it is MP3 already). */
"mp3";

/**  One export job, as Downloads → Exports lists it. */
export type ExportJob = {
	id: string,
	/**  The title, or "3 titles". */
	label: string,
	medium: string,
	format: ExportFormat,
	destination: ExportDestination,
	state: ExportState,
	/**  Chapters downloaded so far / needed, while downloading. */
	downloaded: number,
	toDownload: number,
	/**  Chapters written so far / to write. */
	written: number,
	toWrite: number,
	/**  Names of the files written. */
	files: string[],
	/**  Chapters left out (their download failed). */
	failedChapters: number,
	/**  Pages left out of a PDF (formats it can't hold). */
	skippedPages: number,
	message: string | null,
	startedAt: number | null,
	/**  How far the file being converted is, 0 to 1 (videos re-encoded or copied into a format). */
	progress: number | null,
};

/**  What an export would do, shown before it starts. */
export type ExportPlan = {
	chapters: number,
	/**  Chapters that must download first. */
	missing: number,
	/**  Files the export will write. */
	files: number,
	/**  Why it can't run as asked, if so (e.g. a video stream with separate audio). */
	problem: string | null,
	/**  Videos: what each format does with the episodes downloaded so far. */
	conversions: ExportConversion[],
};

export type ExportRequest = {
	medium: string,
	titleIds: string[],
	scope: ExportScope,
	format: ExportFormat,
	destination: ExportDestination,
	/**
	 *  A folder chosen in the export sheet: with `destination` `folder`, files go there instead
	 *  of the one set in Settings → Downloads.
	 */
	folder: ExportFolder | null,
};

/**  Which chapters or episodes of each title an export takes. */
export type ExportScope = { kind: "all" } | 
/**  Only those already downloaded: nothing is fetched. */
{ kind: "downloaded" } | { kind: "unread" } | 
/**  From one chapter to another, inclusive, in reading order (one title). */
{ kind: "range"; from: string; to: string } | 
/**  Exactly these. */
{ kind: "chosen"; ids: string[] };

export type ExportState = 
/**  Waiting for chapters to download. */
"downloading" | "writing" | "done" | "failed" | "cancelled";

